// Builds the envelope from the request your HR system sends to this webhook.
// Settings: replace with your own values.
const TEMPLATE_URL = 'REPLACE_WITH_YOUR_TEMPLATE_URL'; // the stored employment-contract template
const EMPLOYER = { name: 'Acme Corp', address: '100 Example Street, Springfield' };
const HR_APPROVER = { name: 'Alex Chen', email: 'alex.chen@example.com' };
const EMPLOYER_SIGNER = { name: 'John Smith', email: 'john.smith@example.com', title: 'Head of Operations' };

const input = $input.first().json.body;
if (!input?.employee?.name || !input?.employee?.email) {
  throw new Error('The request needs employee.name and employee.email');
}

const envelope = {
  title: `Employment contract: ${input.employee.name}`,
  message: 'Please review and sign your employment contract.',
  routing: 'sequential', // recipients act in array order: HR, then employer, then employee
  metadata: input.reference ? { hr_reference: String(input.reference) } : {},
  documents: [
    {
      key: 'contract',
      url: TEMPLATE_URL,
      format: 'docx',
      data: {
        city: 'Springfield',
        contractDate: new Date().toISOString().slice(0, 10),
        employer: { ...EMPLOYER, signatory: EMPLOYER_SIGNER.name, signatoryTitle: EMPLOYER_SIGNER.title },
        employee: { name: input.employee.name, address: input.employee.address ?? '' },
        startDate: input.start_date,
        jobTitle: input.job_title,
        hasProbation: Boolean(input.has_probation),
        probationMonths: String(input.probation_months ?? '3'),
        weeklyHours: String(input.weekly_hours ?? '40'),
        currency: input.currency ?? 'USD',
        salary: String(input.salary),
        vacationDays: String(input.vacation_days ?? '25'),
        governingLaw: 'the State of Delaware',
      },
      places: [
        { key: 'employer_signs_here', type: 'signature', recipient_key: 'employer' },
        { key: 'employee_signs_here', type: 'signature', recipient_key: 'employee' },
      ],
    },
  ],
  recipients: [
    { type: 'approver', key: 'hr', ...HR_APPROVER },
    { type: 'signer', key: 'employer', name: EMPLOYER_SIGNER.name, email: EMPLOYER_SIGNER.email },
    { type: 'signer', key: 'employee', name: input.employee.name, email: input.employee.email },
  ],
};

return [{ json: { envelope } }];
